overlay.ops/backup.sh:
#!/bin/sh
# Nightly backup of /var/data. Gives up if the data lock is held.
flock -n /var/lock/app-data.lock tar czf /backup/data-$(date +%F).tgz /var/data || { echo "backup: lock busy" >&2; exit 75; }

overlay.ops/rotate-logs.sh:
#!/bin/sh
# Rotates and compresses logs under /var/data/logs; holds the data lock while it runs (about 6 minutes).
flock /var/lock/app-data.lock sh -c 'gzip -9 /var/data/logs/*.log && mv /var/data/logs/*.gz /var/data/archive/'
